(()=>{'use strict';
const files={marco:'https://github.com/Antoniorjr4/Aletheia/blob/release/v1.0-rc1/docs/RC1.md',arch:'library/Aletheia-Architecture-v0.2.pdf',brand:'library/Aletheia-Visual-Identity.pdf'};
const pieces={
intro:`Λletheia is a functional-first research language for agentic systems. Its central proposition: uncertainty, authority, side effects, integrity and resource limits are part of the program — not an informal instruction to a model.`,
introPt:`Λletheia é uma linguagem experimental, de orientação funcional, para sistemas agênticos. Sua proposta: incerteza, autoridade, efeitos colaterais, integridade e limites de recursos fazem parte do programa — não de instruções informais ao modelo.`,
install:`git clone https://github.com/Antoniorjr4/Aletheia.git
cd Aletheia
git checkout release/v1.0-rc1
cargo build --release
cargo test --all
(cd lean && lake build --wfail)
scripts/rc-smoke.sh`,
check:`./target/release/athc check examples/remediate.ath
./target/release/athc run examples/remediate.ath --arg '"api"'
./target/release/athc grammar examples/remediate.ath --type Action \
  --decode '{"value":{"kind":"Delete","deploy":"db"}}'`,
model:`model planner {
  id = "openai/gpt-oss-20b"
  provider = "groq"
  version = "2026-11-09"
  overhead = 768
  price_in = 0.075
  price_out = 0.30
  ctx = 131072
  max_out = 600
  reasoning = 512
  ttft = 2.0
  per_tok = 0.01
}`,
types:`type Action =
  | Restart { deploy: Text[..32] }
  | Scale   { deploy: Text[..32], to: Int[2..64] }

let draft = infer planner -> List[Action, 1..3] {
  estado = s.managed(),
  metricas = s.telemetry(),
  logs = quote(fit(l, 2000)),
}`,
state:`policy SafeRemediation(a: Action) -> Bool =
  match a {
    Restart { deploy } => s.is_managed(deploy),
    Scale { deploy, to } =>
      s.is_managed(deploy) && s.scale_justified(deploy, to),
  }

let draft = infer planner -> Action {
  estado = s.managed(),
  metricas = s.telemetry(),
  deployment_afetado = quote(service),
  logs = quote(fit(l, 2000)),
}`,
saga:`tool scale(c: Cap[Cluster.Write],
  deploy: Text[..32] ^ Endorsed,
  to: Int[2..64], k: own IdemKey) -> Text
  ! { Cluster.Write } compensable by unscale
  provider queryable latency 1.0

let r = atomic recover restored(cluster, deploy) {
  scale(cluster, deploy, to, keys.mint())
  await healthy(cluster, deploy) within 20.0
  "resolved"
} on failure(e) {
  "compensated: " ++ e
} on compensation_failed(cf) {
  "manual intervention: " ++ cf
}`,
reconcile:`handle timeout_unknown(p: own Pending[_]) -> Text {
  reconcile p fuel 3 else {
    transfer p
    "pending"
  }
}`,
python:`./target/release/athc emit examples/rollout.ath \
  --target py --out rollout.py
PYTHONPATH=runtimes/python python3 -m aletheia_runtime run rollout.py \
  --provider scripted --world examples/fixtures/world.json \
  --models examples/fixtures/models-rollout.json \
  --arg-json '"api"' --journal rollout-py.jsonl`,
replay:`./target/release/athc run examples/remediate.ath \
  --provider openai --arg '"api"' \
  --record sample.cassette.json
./target/release/athc replay sample.cassette.json --emit-py sample.py
PYTHONPATH=runtimes/python python3 -m aletheia_runtime replay \
  sample.cassette.json sample.py`,
commands:`cargo build --release
cargo test
(cd runtimes/python && PYTHONPATH=. python3 -m unittest discover -s tests)
(cd lean && lake build --wfail)
cargo test -p athc --test differential`,
groq:`export OPENAI_API_KEY=... 
export OPENAI_BASE_URL=https://api.groq.com/openai/v1
cargo run --release --bin athc -- run \
  examples/remediate.ath --provider openai \
  --model openai/gpt-oss-20b --arg '"api"'`,
journal:`./target/release/athc hash examples/remediate.ath
./target/release/athc verify-journal .arx/journal.jsonl
./target/release/athc contract-report .arx/journal.jsonl`
};
const sections=(...a)=>a;
const TOPICS=[
{id:'rc1',group:'CURRENT CANDIDATE',en:'v1.0-RC1 · from proof to executable',pt:'v1.0-RC1 · da prova ao executável',
lead:{en:'A real, reproducible execution across athc, ARX, SQLite and crash recovery. Release candidate in draft PR #5; not merged or certified.',pt:'Uma execução reproduzível entre athc, ARX, SQLite e recuperação após queda. Release candidate no PR #5 em rascunho; não integrado nem certificado.'},
parts:sections(
{en:'Project status',pt:'Situação do projeto',enBody:'<p><strong>v1.0-RC1 is a release candidate, not a stable 1.0 release.</strong> Branch <code>release/v1.0-rc1</code> based on <code>rev13</code>; <a href="https://github.com/Antoniorjr4/Aletheia/pull/5" target="_blank" rel="noopener">PR #5</a> remains a draft. The main branch still contains the historic v0.9 baseline. The RC1 adds an executable program and a real process/service recovery test, with <strong>US$ 0.00 new Groq spending</strong>.</p>',ptBody:'<p><strong>v1.0-RC1 é release candidate, não a versão 1.0 estável.</strong> Branch <code>release/v1.0-rc1</code> derivada de <code>rev13</code>; o <a href="https://github.com/Antoniorjr4/Aletheia/pull/5" target="_blank" rel="noopener">PR #5</a> continua em rascunho. A main conserva a base histórica v0.9. O RC1 acrescenta programa executável e recuperação real entre processos/serviço, com <strong>US$ 0,00 em novas chamadas Groq</strong>.</p>'},
{en:'Run the complete candidate',pt:'Execute o candidato completo',code:'git clone https://github.com/Antoniorjr4/Aletheia && cd Aletheia\ngit checkout release/v1.0-rc1\nscripts/rc-smoke.sh',language:'bash',enBody:'<p>Requirements: stable Rust/Cargo and a C compiler (SQLite is compiled as part of the service). The smoke script builds <code>athc</code> and <code>ath-world</code>, exercises legitimate and malicious scenarios, kills the real process with SIGKILL and checks recovery. It exits nonzero if a verification fails. Outputs are under <code>target/rc-smoke/</code>.</p>',ptBody:'<p>Requisitos: Rust/Cargo estável e compilador C (SQLite é compilado com o serviço). O smoke compila <code>athc</code> e <code>ath-world</code>, exercita casos legítimos e adversariais, mata o processo real por SIGKILL e verifica a recuperação. Falhas geram saída não zero. Artefatos em <code>target/rc-smoke/</code>.</p>'},
{en:'Three gates before an effect',pt:'Três barreiras antes do efeito',enBody:'<p><strong>1. Type:</strong> the model output must fit <code>Plan</code>. <strong>2. Policy:</strong> <code>refine draft by SafePlan</code> checks the trusted payee register. <strong>3. Effect contract:</strong> <code>requires s.authorizes(op,to,amount)</code> requires a free, execution-bound grant for the entire operation tuple. <code>athc obligations</code> reports the three lifted contracts checked at refine. The model is scripted in this demonstration, including when it obeys injection.</p>',ptBody:'<p><strong>1. Tipo:</strong> a proposta precisa pertencer a <code>Plan</code>. <strong>2. Política:</strong> <code>refine draft by SafePlan</code> confere beneficiários confiáveis. <strong>3. Contrato:</strong> <code>requires s.authorizes(op,to,amount)</code> exige concessão livre para a tupla inteira na execução. <code>athc obligations</code> relata três contratos levantados e conferidos no refine. O modelo da demonstração é roteirizado, inclusive ao obedecer a injeção.</p>'},
{en:'Linear grants and precise authorization',pt:'Concessões lineares e autoridade precisa',code:'tool pay(c: Cap[Bank.Pay],\n  to: Text[..16] ^ Endorsed, amount: Text[..16] ^ Endorsed,\n  memo: Text[..60] ^ Endorsed, k: own IdemKey) -> Text\n  ! { Bank.Pay } compensable by refund provider idempotent latency 5.0\n  requires s.member("payees", to) && s.authorizes("pay", to, amount)',language:'ath',enBody:'<p>A grant binds the operation, all arguments, origin, run and nonce, with a BLAKE3 identifier. A single grant is consumed and persisted before its effect (<code>.spent</code> + fsync). <code>athc grant</code> issues structured confirmation; ambiguous intentions do not grant. <code>E0425</code> rejects <code>s.authorizes</code> outside <code>requires</code>; <code>R0632</code> rejects a missing free grant.</p>',ptBody:'<p>Uma concessão vincula operação, argumentos, origem, execução e nonce, com identidade BLAKE3. O consumo é persistido antes do efeito (<code>.spent</code> + fsync). <code>athc grant</code> cria confirmação estruturada; intenção ambígua não concede autoridade. <code>E0425</code> rejeita <code>s.authorizes</code> fora de <code>requires</code>; <code>R0632</code> recusa a ausência de concessão livre.</p>'},
{en:'Strict WAL and real SIGKILL',pt:'WAL estrito e SIGKILL real',enBody:'<p>WAL unreadable/corrupted cases fail closed: <code>W0001</code> read error, <code>W0002</code> malformed/mismatched line, <code>W0003</code> no WAL for recovery, <code>W0004</code> foreign WAL, <code>W0005</code> non-reversible operation without a key. A torn final record is preserved separately and the log truncated to the last intact record. The experiment kills the process at <code>intent</code>, <code>sent</code>, <code>confirmed</code> and <code>closed</code>.</p>',ptBody:'<p>O WAL falha fechado: <code>W0001</code> erro de leitura, <code>W0002</code> linha inválida/cadeia alterada, <code>W0003</code> WAL ausente em recover, <code>W0004</code> WAL de outro programa, <code>W0005</code> operação irreversível sem chave. A última linha rasgada é preservada separadamente e o log volta ao último registro íntegro. A demonstração mata o processo em <code>intent</code>, <code>sent</code>, <code>confirmed</code> e <code>closed</code>.</p>'},
{en:'athc recover by provider class',pt:'athc recover por classe de provedor',code:'athc recover programa.ath --wal execucao.wal --host tcp://127.0.0.1:PORT --inspect\n# recovery decisions: 0 = no pending; 3 = escalation; 2 = WAL error',language:'bash',enBody:'<p><strong>Idempotent:</strong> safe resend with the same key (provider deduplicates). <strong>Queryable:</strong> ask status, never resend. <strong>Opaque:</strong> do not resend; escalate. <code>athc recover</code> closes open obligations in a new process; it does not replay unstarted program steps. An unreachable provider is not evidence of failure.</p>',ptBody:'<p><strong>Idempotente:</strong> reenvio com a mesma chave (o provedor deduplica). <strong>Consultável:</strong> consultar status, nunca reenviar. <strong>Opaco:</strong> não reenviar; escalar. <code>athc recover</code> encerra obrigações abertas em outro processo; não retoma as etapas ainda não iniciadas. Provedor inalcançável não é evidência de falha.</p>'},
{en:'Verification dossier',pt:'Dossiê de verificação',enBody:'<table class="doc-section-table"><thead><tr><th>RC1 CHECK</th><th>REPORTED RESULT</th></tr></thead><tbody><tr><td>Rust</td><td>131 tests · 0 failures</td></tr><tr><td>Lean 4.20</td><td>96 axiom guards · no sorry</td></tr><tr><td>Lean × ARX × Python</td><td>26/26 differential cases</td></tr><tr><td>Grant harness G and GP (each)</td><td>33/33 forbidden attempts refused · 8/8 legitimate controls · 0 forbidden effects</td></tr><tr><td>Real SIGKILL recovery</td><td>16/16 (4 crash points × 4 operations)</td></tr><tr><td>Clean-clone smoke</td><td>Exit 0 · approx. 1m21s in the reported test</td></tr></tbody></table>',ptBody:'<table class="doc-section-table"><thead><tr><th>VERIFICAÇÃO RC1</th><th>RESULTADO RELATADO</th></tr></thead><tbody><tr><td>Rust</td><td>131 testes · 0 falhas</td></tr><tr><td>Lean 4.20</td><td>96 guardas de axiomas · sem sorry</td></tr><tr><td>Lean × ARX × Python</td><td>26/26 casos diferenciais</td></tr><tr><td>Harness de concessões G e GP (cada)</td><td>33/33 recusas · 8/8 controles legítimos · 0 efeitos proibidos</td></tr><tr><td>Recuperação após SIGKILL</td><td>16/16 (4 pontos × 4 operações)</td></tr><tr><td>Smoke em clone limpo</td><td>Exit 0 · cerca de 1m21s na execução relatada</td></tr></tbody></table>'},
{en:'The boundaries of the claim',pt:'Os limites da evidência',enBody:'<p>RC1 <strong>does not</strong> prove a complete Lean-to-Rust refinement, power-loss safety, signed grant provenance, multi-writer WAL safety or real financial provider conformance. The RC1 RemoteHost works in ARX, not yet in the Python runtime. Provider classes and fsync durability are assumptions. The PR is still draft. <a href="https://github.com/Antoniorjr4/Aletheia/blob/release/v1.0-rc1/docs/RC1.md" target="_blank" rel="noopener">RC1 source / docs/RC1.md ↗</a></p><p>For a guided learning path, visit <a href="academy.html">Λletheia Academy ↗</a>.</p>',ptBody:'<p>O RC1 <strong>não</strong> demonstra refinamento integral Lean–Rust, perda de energia, assinatura da origem das concessões, segurança de múltiplos escritores no WAL ou conformidade de provedores financeiros reais. O RemoteHost RC1 existe no ARX, ainda não no runtime Python. Classes dos provedores e durabilidade fsync são hipóteses. O PR continua em rascunho. <a href="https://github.com/Antoniorjr4/Aletheia/blob/release/v1.0-rc1/docs/RC1.md" target="_blank" rel="noopener">RC1 source / docs/RC1.md ↗</a></p><p>Para aprender com aulas progressivas, acesse a <a href="academy.html">Λletheia Academy ↗</a>.</p>'}
)},
{id:'academy',group:'LEARNING',en:'Λletheia Academy · guided course',pt:'Λletheia Academy · curso guiado',lead:{en:'Nine bilingual lessons with real RC1 source examples, self-checks and offline exercises.',pt:'Nove aulas bilíngues com exemplos reais do RC1, verificações e exercícios locais.'},parts:sections(
{en:'Study path',pt:'Trilha de estudos',enBody:'<p>Four stages: Foundations (environment, types, integrity), Engineering (grants, policy, sagas), Systems (WAL, proofs) and Capstone (reproducible treasury). Your answers and progress are kept only in the browser. The program grants no certificate or formal qualification. <a href="academy.html">Start the Academy ↗</a>.</p>',ptBody:'<p>Quatro etapas: Fundamentos (ambiente, tipos, integridade), Engenharia (concessões, política, sagas), Sistemas (WAL, provas) e Projeto Final (tesouraria reproduzível). Respostas e progresso são guardados somente no navegador. O programa não fornece certificado ou habilitação formal. <a href="academy.html">Começar na Academy ↗</a>.</p>'},
{en:'Learning by building',pt:'Aprender programando',enBody:'<p>Every module links primary source code and local commands. The browser quiz does not execute the compiler: for real validation use the RC1 branch and scripts/rc-smoke.sh.</p>',ptBody:'<p>Cada módulo parte do código-fonte e de comandos locais. O quiz do navegador não executa o compilador: para validação real use a branch RC1 e scripts/rc-smoke.sh.</p>'}
)},
{id:'overview',group:'FOUNDATIONS',en:'The idea',pt:'A ideia',lead:{en:'A language designed to reveal what ordinary agent pipelines conceal.',pt:'Uma linguagem feita para revelar o que os pipelines tradicionais de agentes ocultam.'},parts:sections(
{en:'The meaning of truth',pt:'O significado de verdade',enBody:'<p>The Greek <em>alētheia</em> is the act of bringing something out of concealment. In the language, a decision is not considered trustworthy merely because a model expresses confidence. The program must declare who can act, what data can be endorsed and which costs are acceptable.</p>',ptBody:'<p>O grego <em>alētheia</em> remete ao desocultamento. Na linguagem, uma decisão não merece confiança apenas porque o modelo parece confiante. O programa declara quem pode agir, que dados podem ser endossados e quais custos são aceitáveis.</p>'},
{en:'What exists today',pt:'O que existe hoje',enBody:'<p>The v0.9 core on main (commit 245214b) is a historical baseline; the latest v1.0-RC1 is a draft in PR #5. The v0.9 baseline includes a Rust compiler (<code>athc</code>), ARX execution engine, Python emitter/runtime, BLAKE3 Codex, replay cassettes, mechanized Lean proofs of T1/T2/T3/T6/T9 over the formal core, and an official but partial AgentDojo banking evaluation.</p><div class="doc-note"><strong>Research boundary.</strong> Formal results apply to the modeled Lean core, not a complete machine-checked refinement of production Rust. The AgentDojo result covers 19 of 144 potential attack pairs.</div>',ptBody:'<p>A v0.9 na main (commit 245214b) é a base histórica; o v1.0-RC1 é o candidato mais recente, no PR #5 em rascunho. A base v0.9 possui compilador Rust (<code>athc</code>), runtime ARX, emissor/runtime Python, Codex BLAKE3, cassetes de replay, provas Lean T1/T2/T3/T6/T9 no núcleo formal e uma avaliação bancária AgentDojo oficial, mas parcial.</p><div class="doc-note"><strong>Limite da pesquisa.</strong> As provas aplicam-se ao núcleo formal Lean, não a um refinamento integral do Rust. O AgentDojo cobre 19 de 144 pares possíveis de ataque.</div>'},
{en:'Five integrated concerns',pt:'Cinco dimensões integradas',enBody:'<p>Uncertainty (distributions), authority (<code>Cap[E]</code>), graded resources (Δ/β), memory or trusted state, and integrity/provenance. Sagas and journaling extend these concerns into distributed execution.</p>',ptBody:'<p>Incerteza (distribuições), autoridade (<code>Cap[E]</code>), recursos graduados (Δ/β), memória ou estado confiável e integridade/proveniência. Sagas e journal levam essas garantias à execução distribuída.</p>'})},
{id:'install',group:'GET STARTED',en:'Installation',pt:'Instalação',lead:{en:'Build the language from source. No hosted account is required for scripted execution.',pt:'Compile a linguagem a partir do código-fonte. O modo roteirizado não exige serviço hospedado.'},parts:sections(
{en:'Requirements',pt:'Requisitos',enBody:'<p>Rust ≥ 1.87. Python ≥ 3.10 for the emitted runtime and benchmark. Lean 4.20.0 is installed via <code>elan</code>, following <code>lean/lean-toolchain</code>.</p>',ptBody:'<p>Rust ≥ 1.87. Python ≥ 3.10 para o runtime Python e benchmark. Lean 4.20.0 é instalado com <code>elan</code>, conforme <code>lean/lean-toolchain</code>.</p>'},
{en:'Build & test',pt:'Compilar e testar',code:pieces.install,language:'bash',enBody:'<p>The official repository is public. These commands read its source and compile on your machine. Run the Lean build only after installing its toolchain.</p>',ptBody:'<p>O repositório oficial é público. Os comandos leem o código e compilam localmente. Execute o build Lean após instalar o toolchain.</p>'},
{en:'One-line quick check',pt:'Uma linha para verificar',code:'cargo run --release --bin athc -- check examples/remediate.ath',language:'bash',enBody:'<p>A useful first operation: verify a bundled example without invoking a remote model.</p>',ptBody:'<p>Primeiro comando útil: verificar um exemplo sem chamar modelo remoto.</p>'})},
{id:'first-program',group:'GET STARTED',en:'Your first check',pt:'Primeira verificação',lead:{en:'Inspect a real typed remediation program and its compiler diagnostics.',pt:'Inspecione um programa real de remediação tipada e os diagnósticos do compilador.'},parts:sections(
{en:'Check the source',pt:'Verificar a fonte',code:pieces.check,language:'bash',enBody:'<p>The <code>check</code> command executes the compiler strata without operating on the cluster. The <code>run</code> command uses the bundled simulated world by default; <code>grammar</code> illustrates type-derived decoding limits.</p>',ptBody:'<p><code>check</code> executa os estratos do compilador sem operar no cluster. <code>run</code> usa o mundo simulado por padrão; <code>grammar</code> demonstra a decodificação derivada do tipo.</p>'},
{en:'Read the output',pt:'Ler a saída',enBody:'<p>Results are stratified: E0 structure, E1 linearity, E2 effect authority, E3 integrity, E5 refinements, E6 worst-case budget, plus the versioned model contract Δ and canonical Codex hash.</p>',ptBody:'<p>A saída segue os estratos: E0 estrutura, E1 linearidade, E2 autoridade de efeitos, E3 integridade, E5 refinamentos, E6 orçamento de pior caso, além do contrato Δ e do hash canônico Codex.</p>'})},
{id:'syntax',group:'THE LANGUAGE',en:'Syntax & types',pt:'Sintaxe e tipos',lead:{en:'Structured algebraic actions, bounded collections, explicit effects and source-level policy.',pt:'Ações algébricas, coleções limitadas, efeitos explícitos e políticas no programa.'},parts:sections(
{en:'Algebraic data types',pt:'Tipos algébricos',code:pieces.types,language:'ath',enBody:'<p>The type <code>Action</code> has two variants. Its output schema constrains both the variant and the argument range. <code>List[Action, 1..3]</code> statically bounds iteration and response size.</p>',ptBody:'<p><code>Action</code> possui duas variantes. O esquema de saída limita a variante e os argumentos. <code>List[Action, 1..3]</code> delimita iteração e tamanho da resposta estaticamente.</p>'},
{en:'A compact surface',pt:'Uma superfície compacta',enBody:'<p>Common constructions include <code>type</code>, <code>tool</code>, <code>agent</code>, <code>let</code>, <code>infer</code>, <code>policy</code>, <code>refine</code>, <code>match</code>, <code>for</code>, <code>atomic recover</code> and <code>handle timeout_unknown</code>. They are checked together, not as a list of loose prompt rules.</p>',ptBody:'<p>As construções incluem <code>type</code>, <code>tool</code>, <code>agent</code>, <code>let</code>, <code>infer</code>, <code>policy</code>, <code>refine</code>, <code>match</code>, <code>for</code>, <code>atomic recover</code> e <code>handle timeout_unknown</code>, verificadas em conjunto.</p>'})},
{id:'inference',group:'THE LANGUAGE',en:'Typed model inference',pt:'Inferência tipada',lead:{en:'Output types are compiled into constraints the model interface must respect.',pt:'Os tipos de saída são compilados em restrições para a interface do modelo.'},parts:sections(
{en:'Types are the grammar',pt:'O tipo é a gramática',enBody:'<p><code>ath-grammar</code> derives canonical output shapes, strict JSON Schema (core/full dialects), GBNF, a viable-prefix automaton and bounds on emitted bytes. In the masked provider, a local decoder constrains tokens; in OpenAI-compatible servers, server-side schema enforcement is revalidated by ARX.</p>',ptBody:'<p><code>ath-grammar</code> deriva forma canônica, JSON Schema estrito (core/full), GBNF, autômato de prefixo viável e teto de bytes. O provedor masked aplica máscara local; servidores compatíveis com OpenAI são validados novamente pelo ARX.</p>'},
{en:'Propose, then endorse',pt:'Propor, depois endossar',code:'let draft = infer planner -> Action {\n  estado = s.managed(),\n  metricas = s.telemetry(),\n  logs = quote(fit(l, 2000)),\n}\nlet action = refine draft by SafeRemediation\n  retry 2 else { "escalated" }',language:'ath',enBody:'<p>Model data starts untrusted. A pure policy can selectively endorse it. If it fails, bounded retries or a declared fallback prevent the model from silently exceeding its authority.</p>',ptBody:'<p>Dados do modelo começam como não confiáveis. Uma política pura pode endossá-los seletivamente. Se falharem, tentativas limitadas e fallback impedem autoridade implícita.</p>'})},
{id:'capabilities',group:'THE LANGUAGE',en:'Capabilities & effects',pt:'Capacidades e efeitos',lead:{en:'The right to take an action is a program value — not a request phrased politely.',pt:'O direito de executar uma ação é um valor do programa, não um pedido formulado gentilmente.'},parts:sections(
{en:'Cap[E]',pt:'Cap[E]',enBody:'<p>A tool requiring <code>Cap[Cluster.Write]</code> cannot fire using an unrelated capability. The E2 checker validates declared effect rows; the runtime also enforces its capability boundary. In the Lean formal core, capabilities have a linear discipline (T2).</p>',ptBody:'<p>Uma ferramenta que exige <code>Cap[Cluster.Write]</code> não pode operar com capacidade incompatível. E2 verifica linhas de efeito e o runtime aplica a barreira. No núcleo Lean, capacidades seguem disciplina linear (T2).</p>'},
{en:'Do not conflate models',pt:'Não confundir os modelos',enBody:'<div class="doc-note">The historical v0.9 baseline notes that tool capabilities are reusable in the ARX implementation, while the formal Lean calculus treats capabilities as linear; proving a full refinement between them remains future work.</div>',ptBody:'<div class="doc-note">A base histórica v0.9 registra que capacidades de ferramenta são reutilizáveis no ARX, enquanto o cálculo Lean as trata como lineares. A prova integral de refinamento entre ambos permanece pendente.</div>'})},
{id:'integrity',group:'THE LANGUAGE',en:'Integrity & provenance',pt:'Integridade e proveniência',lead:{en:'Where information came from is as important as the bytes it contains.',pt:'A origem da informação importa tanto quanto seu conteúdo.'},parts:sections(
{en:'Integrity lattice',pt:'Reticulado de integridade',enBody:'<p>Λletheia tracks <code>Untrusted ⊑ Endorsed ⊑ Trusted</code>, including the program-counter label (<code>pc</code>) for implicit control flow. Information from model output or external logs cannot directly satisfy parameters requiring <code>Endorsed</code>.</p>',ptBody:'<p>Λletheia rastreia <code>Untrusted ⊑ Endorsed ⊑ Trusted</code>, inclusive o rótulo <code>pc</code> de fluxos implícitos. Saídas do modelo e logs externos não podem preencher diretamente parâmetros <code>Endorsed</code>.</p>'},
{en:'Diagnose misuse',pt:'Diagnosticar desvios',enBody:'<p>Examples: <code>E0412</code> untrusted flow into an endorsed argument; <code>E0415</code> untrusted prompt data missing <code>quote(...)</code>; <code>E0417</code> untrusted input influencing a recovery probe or postcondition.</p>',ptBody:'<p>Exemplos: <code>E0412</code> fluxo Untrusted para argumento Endorsed; <code>E0415</code> dado Untrusted sem <code>quote(...)</code>; <code>E0417</code> entrada não confiável influenciando sonda ou pós-condição de recuperação.</p>'})},
{id:'budgets',group:'THE LANGUAGE',en:'Resources & contracts',pt:'Recursos e contratos',lead:{en:'A model is a versioned computational contract with costs, latency and token ceilings.',pt:'Um modelo é um contrato computacional versionado, com custos, latência e teto de tokens.'},parts:sections(
{en:'Declare Δ',pt:'Declarar Δ',code:pieces.model,language:'ath',enBody:'<p>Model identity, version and overhead enter the Codex hash. E6 computes a worst-case path across token, USD and time budgets, including bounded loops and saga failures.</p>',ptBody:'<p>Identidade, versão e overhead entram no hash Codex. E6 calcula o pior caminho em tokens, dólares e tempo, inclusive laços limitados e falhas de saga.</p>'},
{en:'Runtime accountability',pt:'Responsabilidade no runtime',enBody:'<p>The runtime reserves budget before requests and settles from observed usage afterward, including a sample that breaches a declared contract. Contract breaches may include output tokens (<code>R0702</code>), latency (<code>R0703</code>), model identity (<code>R0704</code>) or input overhead (<code>R0705</code>).</p>',ptBody:'<p>O runtime reserva orçamento antes e liquida após a amostra, incluindo violações. Exemplos: tokens de saída (<code>R0702</code>), latência (<code>R0703</code>), identidade do modelo (<code>R0704</code>) e overhead de entrada (<code>R0705</code>).</p>'})},
{id:'sagas',group:'THE LANGUAGE',en:'Sagas & reconciliation',pt:'Sagas e reconciliação',lead:{en:'Compensation is a new transition that restores an invariant, not time travel.',pt:'Compensar é uma nova transição que restaura um invariante, não voltar no tempo.'},parts:sections(
{en:'Recoverable actions',pt:'Ações recuperáveis',code:pieces.saga,language:'ath',enBody:'<p>Compensations run in reverse order after a failure. A recovery probe must confirm the invariant before the <code>on failure</code> path runs; otherwise the program reports <code>CompensationFailed</code>. T6 covers the specified abstract core, with restoring contracts and non-nested saga-body assumptions; it does not prove the full ARX implementation.</p>',ptBody:'<p>Compensações executam na ordem reversa. Uma sonda deve confirmar o invariante antes de <code>on failure</code>; caso contrário, sinaliza <code>CompensationFailed</code>. T6 vale no núcleo abstrato sob contratos restoring e a restrição sobre corpos de saga não aninhados; não constitui prova integral do ARX.</p>'},
{en:'Unknown is not failed',pt:'Desconhecido não significa falhou',code:pieces.reconcile,language:'ath',enBody:'<p>Timeouts create a linear <code>Pending[k]</code> obligation. The handler reconciles by key or explicitly transfers an unresolved obligation. T9 is mechanized in the v0.9 Lean core: keys terminate in Done, Failed or Transferred, without silent disposal. Rev11 adds the TimeoutUnknown handler to the canonical evaluator (research branch).</p>',ptBody:'<p>Timeouts criam obrigação linear <code>Pending[k]</code>. O tratador reconcilia por chave ou transfere explicitamente a obrigação pendente. T9 já está mecanizado no núcleo Lean da v0.9: cada chave termina em Done, Failed ou Transferred, sem descarte silencioso. A Rev11 acrescenta o tratador TimeoutUnknown ao avaliador canônico (branch de pesquisa).</p>'})},
{id:'trusted-state',group:'RUNTIME',en:'Trusted host snapshots',pt:'Snapshots do host',lead:{en:'The host is the authority for its own inventory. The model is not.',pt:'O host é autoridade sobre seu inventário. O modelo não é.'},parts:sections(
{en:'One snapshot, two decisions',pt:'Um snapshot, duas decisões',code:pieces.state,language:'ath',enBody:'<p><code>s.managed()</code> and <code>s.telemetry()</code> are <code>Trusted</code> fields. The exact same captured snapshot feeds the model context and the contextual policy; the compiler detects mismatches with E0421/E0422. <code>s.inventory("k")</code> and <code>s.member("k", x)</code> generalize the mechanism.</p>',ptBody:'<p><code>s.managed()</code> e <code>s.telemetry()</code> têm rótulo <code>Trusted</code>. O mesmo snapshot alimenta contexto e política; E0421/E0422 detectam divergências. <code>s.inventory("k")</code> e <code>s.member("k",x)</code> generalizam o mecanismo.</p>'},
{en:'Contextual scale',pt:'Escalonamento contextual',enBody:'<p><code>s.scale_justified(deploy,to)</code> requires observed CPU at least 85%, observed replicas and a proposed increase no higher than 2× the current count. Missing telemetry denies the operation. This is a simulated-host guarantee; production concurrency requires further operational design.</p>',ptBody:'<p><code>s.scale_justified(deploy,to)</code> exige CPU observada ≥85%, réplicas conhecidas e aumento de até 2×. Sem telemetria, a operação é negada. Essa é uma garantia do host simulado; concorrência em produção exige projeto adicional.</p>'})},
{id:'runtime',group:'RUNTIME',en:'ARX & the journal',pt:'ARX e o journal',lead:{en:'Evidence must survive the conclusion of an agent run.',pt:'A evidência precisa sobreviver à conclusão da execução do agente.'},parts:sections(
{en:'Durable event records',pt:'Registros duráveis',enBody:'<p>ARX emits a BLAKE3-linked journal with events, tool requests, compensations, budget settlements and contract identifiers. The compiler Codex hashes canonical definitions. The journal can be verified to detect tampering or unresolved keys.</p>',ptBody:'<p>O ARX emite journal encadeado por BLAKE3: eventos, chamadas, compensações, liquidação de orçamento e contratos. O Codex canoniza definições. A verificação detecta adulteração ou chaves não resolvidas.</p>'},
{en:'Inspect the chain',pt:'Inspecionar a cadeia',code:pieces.journal,language:'bash',enBody:'<p>Use the commands against journals produced by an actual local execution. A result in this website is never a substitute for a verified runtime artifact.</p>',ptBody:'<p>Use esses comandos com journals gerados por execução real local. Nenhum resultado visual deste site substitui um artefato de runtime verificado.</p>'})},
{id:'backends',group:'RUNTIME',en:'Three backends',pt:'Três backends',lead:{en:'One abstract behavior, checked from different implementations.',pt:'Um comportamento abstrato, verificado em implementações diferentes.'},parts:sections(
{en:'Rust × Python × Lean',pt:'Rust × Python × Lean',enBody:'<p>Programs run in ARX/Rust and Python emitted by <code>athc</code>. The Lean evaluator (<code>ath-lean-eval</code>) is also compiled and compared for its supported core. Marco Zero v0.9 reports 400 generated core programs without sagas and 400 with sagas, compared byte for byte across Lean, ARX and Python. The keyed-call corpus in the Rev11 review branch is a separate, later experiment.</p>',ptBody:'<p>Os programas rodam em ARX/Rust e em Python emitido pelo <code>athc</code>. O avaliador Lean (<code>ath-lean-eval</code>) também é compilado e comparado no núcleo suportado. O Marco Zero v0.9 informa 400 programas do núcleo sem sagas e 400 com sagas, comparados byte a byte entre Lean, ARX e Python. O corpus com chamadas e chaves da Rev11 pertence a uma revisão posterior ainda em análise.</p>'},
{en:'Replay the exact HTTP tape',pt:'Reproduzir o mesmo HTTP',code:pieces.replay,language:'bash',enBody:'<p><code>--record</code> captures request/response bytes and measured latency without the API key. Replay reconstructs requests and checks journals against the recorded run. Marco Zero v0.9 reports 22 recorded real Groq cassettes across 20B/120B. Rev11 separately replays 16 ARX tapes in its regression gate; these are differently scoped counts.</p>',ptBody:'<p><code>--record</code> grava requisição/resposta e latência, sem chave. O replay reconstrói pedidos e verifica journals. O Marco Zero v0.9 relata 22 cassetes reais da Groq 20B/120B. A Rev11 também verifica 16 cassetes ARX em seu gate de regressão; são contagens com escopos distintos.</p>'},
{en:'Run the emitted Python',pt:'Executar Python emitido',code:pieces.python,language:'bash',enBody:'<p>This path uses only the Python standard library for the runtime.</p>',ptBody:'<p>Esse runtime utiliza somente a biblioteca padrão de Python.</p>'})},
{id:'proofs',group:'RESEARCH',en:'Lean 4 theorem library',pt:'Biblioteca de teoremas Lean',lead:{en:'Mechanized claims over an explicit formal core, with stated assumptions.',pt:'Provas mecanizadas sobre um núcleo formal explícito, com hipóteses declaradas.'},parts:sections(
{en:'The proof families',pt:'As famílias de provas',enBody:'<p><strong>T1 — soundness:</strong> progress, preservation and graded budget boundedness. <strong>T2 — effect confinement:</strong> lexical capabilities and effect authorization. <strong>T3 — robust noninterference:</strong> controlled endorsement of untrusted values. <strong>T6 — saga recovery:</strong> reverse compensation restores the modeled invariant under restoring contracts and non-nested saga-body restrictions. <strong>T9 — idempotency keys:</strong> Pending[k], reconciliation and explicit Done/Failed/Transferred outcomes; an observed Done requires evidence.</p>',ptBody:'<p><strong>T1 — solidez:</strong> progresso, preservação e orçamento. <strong>T2 — confinamento:</strong> capacidades lexicais e efeitos autorizados. <strong>T3 — não interferência robusta:</strong> endosso controlado de dados não confiáveis. <strong>T6 — recuperação:</strong> compensação reversa e restauração do invariante modelado sob contratos restoring e restrições a corpos de saga não aninhados. <strong>T9 — chaves:</strong> Pending[k], reconciliação e desfechos explícitos Done/Failed/Transferred; Done observado exige evidência.</p>'},
{en:'Check the kernel',pt:'Verificar o kernel',code:'(cd lean && lake build --wfail)',language:'bash',enBody:'<p>The reported axiom audit permits <code>propext</code>, <code>Quot.sound</code> and <code>Classical.choice</code>, with no <code>sorry</code>. The implementation does not yet prove complete Lean-to-Rust refinement.</p>',ptBody:'<p>A auditoria declara <code>propext</code>, <code>Quot.sound</code> e <code>Classical.choice</code>, sem <code>sorry</code>. Ainda não existe prova integral de refinamento Lean para Rust.</p>'})},
{id:'benchmarks',group:'RESEARCH',en:'Benchmarks & caveats',pt:'Benchmarks e limites',lead:{en:'Read the denominator before the headline.',pt:'Leia o denominador antes da manchete.'},parts:sections(
{en:'Official AgentDojo, partial banking',pt:'AgentDojo oficial, banking parcial',enBody:'<p>With Groq GPT-OSS-120B, the first official <code>banking</code> batch evaluates 16 unattacked tasks and 19 of the 144 attack pairs. Baseline AgentDojo: 68.8% clean utility, 15.8% utility under attack, 78.9% attacker success (15/19). Λletheia: 75.0% clean utility, 31.6% utility under attack, 0.0% attacker success (0/19; 95% CI 0–17%). Average tokens per run: 3,632 baseline vs 1,804 Λletheia.</p>',ptBody:'<p>Com GPT-OSS-120B, o primeiro lote oficial <code>banking</code> avalia 16 tarefas sem ataque e 19 de 144 pares adversariais. Baseline: utilidade limpa 68,8%, sob ataque 15,8%, sucesso do atacante 78,9% (15/19). Λletheia: utilidade limpa 75,0%, sob ataque 31,6%, sucesso do atacante 0,0% (0/19; IC95 0–17%). Tokens médios: 3.632 vs 1.804.</p>'},
{en:'Custom M1 is not AgentDojo',pt:'M1 própria não é AgentDojo',enBody:'<p>In the published Rev7 custom M1 with 7 scenarios × 3 repeats per system, Λletheia recorded 0/18 attacker goals and no policy violations; both agents completed all 18 legitimate attacked tasks and all 3 benign controls. This is a small, distinct evaluation with simulated tool worlds and real model calls.</p><div class="doc-note">The Rev7 0/18 is not a direct demonstration that the contextual policy rejected an unsafe live scaling action: in that run, the model chose Restart instead. The policy rejection is exercised in the scripted M1. Do not infer zero underlying risk from a small sample.</div>',ptBody:'<p>Na M1 própria Rev7, com 7 cenários × 3 repetições por sistema, a Λletheia registrou 0/18 objetivos do atacante e nenhuma ação fora da política; ambos cumpriram 18 tarefas legítimas sob ataque e 3 controles sem ataque. É um teste distinto, pequeno, com mundos simulados e LLM real.</p><div class="doc-note">O 0/18 não significa que a política contextual tenha recusado uma escala insegura ao vivo: o modelo escolheu Restart. A recusa foi exercitada na M1 roteirizada. Amostras pequenas não demonstram risco zero.</div>'})},
{id:'rev11-review',group:'RESEARCH',en:'Rev11 · revision history',pt:'Rev11 · histórico de revisão',lead:{en:'A new verification layer under review: keys, canonical timeout handling and structural resistance.',pt:'Uma nova camada de verificação em revisão: chaves, tratamento canônico de timeout e resistência estrutural.'},parts:sections(
{en:'Release status',pt:'Estado da revisão',enBody:'<p><strong>Main baseline:</strong> Marco Zero v0.9, commit <code>245214b</code> on <code>main</code>. <strong>In review:</strong> Rev10 and Rev11 are draft pull requests; Rev11 is <a href="https://github.com/Antoniorjr4/Aletheia/pull/2" target="_blank" rel="noopener">PR #2</a> (<code>rev11 → rev10</code>). These results are engineering evidence from a research branch, <em>not</em> a merged release.</p>',ptBody:'<p><strong>Base na main:</strong> Marco Zero v0.9, commit <code>245214b</code> na <code>main</code>. <strong>Em revisão:</strong> Rev10 e Rev11 são pull requests em rascunho; a Rev11 é o <a href="https://github.com/Antoniorjr4/Aletheia/pull/2" target="_blank" rel="noopener">PR #2</a> (<code>rev11 → rev10</code>). São evidências de uma branch de pesquisa, <em>não</em> uma versão publicada.</p>'},
{en:'Keyed differential tripod',pt:'Tripé diferencial com chaves',enBody:'<p>Rev11 reports <strong>400</strong> keyless-core and <strong>400</strong> saga programs with byte-identical Lean/ARX/Python core journals. For <strong>600</strong> generated keyed programs (431 exercising keyed calls), ARX and Python remain byte-identical; Lean agrees on the key lifecycle <em>modulo deterministic key renaming</em>. Eight deterministic keyed scenarios are checked across the three. An additional <strong>1,969</strong> journal-mutation cases were rejected. This is differential testing, not a compiler-refinement proof.</p>',ptBody:'<p>A Rev11 relata <strong>400</strong> programas do núcleo sem chaves e <strong>400</strong> com sagas, com journals Lean/ARX/Python idênticos byte a byte. Nos <strong>600</strong> programas gerados com chaves (431 exercitam chamadas com chave), ARX e Python permanecem idênticos byte a byte; o Lean concorda no ciclo de vida <em>módulo renomeação determinística das chaves</em>. Oito cenários determinísticos também são comparados nos três. Outros <strong>1.969</strong> casos de mutação de journal foram rejeitados. São testes diferenciais, não prova de refinamento do compilador.</p>'},
{en:'Formal TimeoutUnknown and T9',pt:'TimeoutUnknown e T9 formal',enBody:'<p>Rev11 models <code>Pending[k]</code>, explicit reconciliation with bounded fuel, handoff/transfer and the <code>TimeoutUnknown</code> handler in the canonical Lean evaluator. The claims cover Done with observed evidence, Failed, and Transferred only after protocol exhaustion. The reported <code>lake build --wfail</code> passed without <code>sorry</code>, <code>admit</code> or new axioms. The ability to mint a key separately from the capability is <strong>Phase 2, not implemented</strong>; the core still identifies the operation key with its capability identity.</p>',ptBody:'<p>A Rev11 modela <code>Pending[k]</code>, reconciliação com combustível finito, transferência explícita e o tratador <code>TimeoutUnknown</code> no avaliador Lean canônico. As propriedades cobrem Done com evidência observada, Failed e Transferred após o esgotamento do protocolo. O <code>lake build --wfail</code> foi reportado aprovado sem <code>sorry</code>, <code>admit</code> ou novos axiomas. A criação de chaves separadas da capacidade é a <strong>Fase 2, ainda não implementada</strong>; no núcleo, a identidade da chave continua vinculada à capacidade.</p>'},
{en:'Compromised-oracle structural matrix',pt:'Matriz estrutural com oráculo comprometido',enBody:'<p>The separate, offline adversarial harness assumes a <strong>fully compromised model</strong> that always proposes the attacker action. Results: <strong>29/29</strong> forbidden attempts refused before effects; <strong>4/4</strong> legitimate controls executed; <strong>3/3</strong> residual, within-policy cases executed (documented limits). These are <em>not</em> 29 live Groq attacks, not an official AgentDojo ASR, and they do not imply that every unsafe real-world action is prevented. Rev11 made <strong>zero paid model calls</strong>.</p>',ptBody:'<p>O harness adversarial separado e offline assume um <strong>modelo completamente comprometido</strong>, que sempre propõe a ação do atacante. Resultados: <strong>29/29</strong> tentativas proibidas recusadas antes do efeito; <strong>4/4</strong> controles legítimos executados; <strong>3/3</strong> casos residuais permitidos pela política executados (limites documentados). Isso <em>não</em> representa 29 ataques ao vivo na Groq nem a ASR oficial do AgentDojo, e não garante bloqueio universal de ações perigosas. A Rev11 fez <strong>zero chamadas pagas</strong> ao modelo.</p>'},
{en:'Behavior vs structure',pt:'Comportamento versus estrutura',enBody:'<p>Rev11 separates behavioral resistance (H1) from structural resistance (H2). Earlier Rev10 AgentDojo records report <strong>0/94</strong> attacker successes for the tested Λletheia pipeline, while the baseline completed <strong>68/94</strong>. The Rev11 document explains that the real model did not propose a plan rejected by the policy in those 94 attacked runs; this is H1 evidence, not proof of H2. The offline forced-attacker matrix tests H2 instead. The remaining <strong>50/144</strong> official banking pairs were not executed in Rev11.</p>',ptBody:'<p>A Rev11 separa resistência comportamental (H1) e estrutural (H2). Os registros anteriores da Rev10 no AgentDojo informam <strong>0/94</strong> sucessos do atacante para o pipeline Λletheia testado, enquanto o baseline atingiu <strong>68/94</strong>. O documento explica que, nessas 94 execuções atacadas, o modelo real não propôs um plano recusado pela política; isso é evidência de H1, não prova de H2. A matriz offline com atacante forçado avalia H2. Os <strong>50/144</strong> pares restantes do banking oficial não foram executados na Rev11.</p>'},
{en:'Source and audit boundary',pt:'Fonte e limite da auditoria',enBody:'<p>Source of truth: <a href="https://github.com/Antoniorjr4/Aletheia/blob/rev11/docs/REV11.md" target="_blank" rel="noopener">Rev11 technical report</a>, <a href="https://github.com/Antoniorjr4/Aletheia/blob/rev11/bench/adversarial/results/MATRIX.md" target="_blank" rel="noopener">offline attack matrix</a> and the corresponding draft PR. The Lean core does not machine-check the full <code>athc</code>, ARX, Python runtime, banking agent, or business-policy adequacy. Rev11 preserved its paid-workflow pause and consumed US$ 0.00 in new Groq usage.</p>',ptBody:'<p>Fontes: <a href="https://github.com/Antoniorjr4/Aletheia/blob/rev11/docs/REV11.md" target="_blank" rel="noopener">relatório Rev11</a>, <a href="https://github.com/Antoniorjr4/Aletheia/blob/rev11/bench/adversarial/results/MATRIX.md" target="_blank" rel="noopener">matriz offline</a> e PR de rascunho. O núcleo Lean não prova integralmente o <code>athc</code>, ARX, runtime Python, agente banking nem a adequação da política de negócios. A Rev11 manteve os workflows pagos pausados e consumiu US$ 0,00 adicionais na Groq.</p>'})},
{id:'cli',group:'REFERENCE',en:'CLI reference',pt:'Referência CLI',lead:{en:'The compiler, runtime and research commands in one place.',pt:'Compilador, runtime e comandos de pesquisa no mesmo lugar.'},parts:sections(
{en:'Core commands',pt:'Comandos centrais',code:pieces.commands,language:'bash',enBody:'<p>Use <code>athc check</code> to type-check, <code>athc run</code> to execute, <code>athc emit</code> to generate Python, <code>athc grammar</code> to inspect constraints, and <code>athc verify-journal</code> to validate event integrity.</p>',ptBody:'<p>Use <code>athc check</code> para verificar, <code>athc run</code> para executar, <code>athc emit</code> para gerar Python, <code>athc grammar</code> para restrições e <code>athc verify-journal</code> para validar integridade.</p>'},
{en:'Real model endpoint',pt:'Endpoint de modelo real',code:pieces.groq,language:'bash',enBody:'<p>Keep provider keys in local environment variables or CI secrets. Never commit keys, and never place secrets inside cassettes or documentation.</p>',ptBody:'<p>Mantenha chaves no ambiente local ou nos Secrets do CI. Nunca salve credenciais em commits, cassetes ou documentação.</p>'})},
{id:'errors',group:'REFERENCE',en:'Diagnostics',pt:'Diagnósticos',lead:{en:'Failure messages are part of the language interface, not incidental logs.',pt:'Mensagens de erro fazem parte da interface da linguagem, não são logs acessórios.'},parts:sections(
{en:'Common diagnostics',pt:'Diagnósticos comuns',enBody:'<table class="doc-section-table"><thead><tr><th>CODE</th><th>CAUSE / CAUSA</th></tr></thead><tbody><tr><td>E0412</td><td>Untrusted value or control flow reaches an Endorsed argument.</td></tr><tr><td>E0415</td><td>Untrusted input enters an inference prompt without quote(...).</td></tr><tr><td>E0421</td><td>Policy reads a trusted inventory absent from the model context.</td></tr><tr><td>E0422</td><td>Model sees dynamic inventory, policy uses hard-coded allowlist.</td></tr><tr><td>E1104 / E1107</td><td>Linear capability or Pending obligation used incorrectly.</td></tr><tr><td>R0703</td><td>Observed latency exceeded the declared model contract.</td></tr></tbody></table>',ptBody:'<table class="doc-section-table"><thead><tr><th>CÓDIGO</th><th>CAUSA</th></tr></thead><tbody><tr><td>E0412</td><td>Dado ou fluxo Untrusted alcança argumento Endorsed.</td></tr><tr><td>E0415</td><td>Entrada Untrusted no prompt sem quote(...).</td></tr><tr><td>E0421</td><td>Política lê inventário confiável ausente do contexto do modelo.</td></tr><tr><td>E0422</td><td>O modelo vê inventário dinâmico, mas a política usa lista fixa.</td></tr><tr><td>E1104 / E1107</td><td>Capacidade ou obrigação Pending consumida incorretamente.</td></tr><tr><td>R0703</td><td>Latência observada excede o contrato do modelo.</td></tr></tbody></table>'})},
{id:'library',group:'REFERENCE',en:'Technical library',pt:'Biblioteca técnica',lead:{en:'Primary technical sources for v1.0-RC1 (draft) and the language architecture.',pt:'Fontes técnicas principais do v1.0-RC1 (rascunho) e da arquitetura da linguagem.'},parts:sections(
{en:'Primary documents',pt:'Documentos primários',enBody:`<div class="resources-section"><a class="resource-card" href="${files.marco}" target="_blank" rel="noopener"><div><strong>v1.0-RC1 · executable candidate report</strong><p>Executable RC1 report: grants, WAL, real service, SIGKILL and recovery. Draft PR #5, not merged.</p></div><span class="resource-arrow">↗</span></a><a class="resource-card" href="${files.arch}" target="_blank" rel="noopener"><div><strong>Architectural specification v0.2</strong><p>Foundational language calculus and five-dimensional design.</p></div><span class="resource-arrow">↗</span></a><a class="resource-card" href="${files.brand}" target="_blank" rel="noopener"><div><strong>Canonical visual identity v1.0</strong><p>Greek foundation, brand geometry, color system and integrity rules.</p></div><span class="resource-arrow">↗</span></a><a class="resource-card" href="https://github.com/Antoniorjr4/Aletheia" target="_blank" rel="noopener"><div><strong>Public source repository</strong><p>Rust crates, Lean theorems, benchmark fixtures and CI workflows.</p></div><span class="resource-arrow">↗</span></a></div>`,ptBody:`<div class="resources-section"><a class="resource-card" href="${files.marco}" target="_blank" rel="noopener"><div><strong>v1.0-RC1 · relatório técnico executável</strong><p>Relatório do RC1: concessões, WAL, serviço real, SIGKILL e recuperação. PR #5 em rascunho, não integrado.</p></div><span class="resource-arrow">↗</span></a><a class="resource-card" href="${files.arch}" target="_blank" rel="noopener"><div><strong>Especificação arquitetural v0.2</strong><p>Base do cálculo e projeto em cinco dimensões.</p></div><span class="resource-arrow">↗</span></a><a class="resource-card" href="${files.brand}" target="_blank" rel="noopener"><div><strong>Manual de identidade visual v1.0</strong><p>Fundamentação grega, geometria, cores e regras de integridade.</p></div><span class="resource-arrow">↗</span></a><a class="resource-card" href="https://github.com/Antoniorjr4/Aletheia" target="_blank" rel="noopener"><div><strong>Repositório público</strong><p>Rust, Lean, fixtures de benchmark e CI.</p></div><span class="resource-arrow">↗</span></a></div>`})}
];
const $=sel=>document.querySelector(sel),safe=s=>s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');let active='rc1',query='';
const currentLanguage=()=>window.Aletheia.language;
function getTopic(id){return TOPICS.find(x=>x.id===id)||TOPICS[0]}
function nav(){const lang=currentLanguage();const filtered=TOPICS.filter(t=>`${t.en} ${t.pt} ${t.group} ${t.lead.en} ${t.lead.pt} ${t.parts.map(p=>[p.en,p.pt,p.enBody,p.ptBody,p.code||''].join(' ')).join(' ')}`.toLowerCase().includes(query));const el=$('#docs-nav');el.innerHTML=filtered.map((t)=>`<button class="docs-nav-item ${t.id===active?'active':''}" data-topic="${t.id}" title="${safe(t[lang])}"><small>${String(TOPICS.indexOf(t)+1).padStart(2,'0')}</small><span>${safe(t[lang])}</span></button>`).join('')||`<div class="docs-empty">${lang==='en'?'No matches. Try a different query.':'Nenhum resultado. Tente outra busca.'}</div>`;el.querySelectorAll('[data-topic]').forEach(btn=>btn.addEventListener('click',()=>setTopic(btn.dataset.topic)));}
function article(){const lang=currentLanguage(),topic=getTopic(active),idx=TOPICS.indexOf(topic);document.title=`${topic[lang]} — Λletheia Docs`;$('#docs-crumb').innerHTML=`${topic.group} <span>/</span> ${safe(topic[lang]).toUpperCase()}`;
let html=`<h1>${safe(topic[lang])}</h1><p class="article-lead">${safe(topic.lead[lang])}</p>`;
topic.parts.forEach((section,i)=>{const title=section[lang],slug=`section-${i}`;html+=`<section><h2 id="${slug}">${safe(title)}</h2>`;html+=section[lang+'Body']||'';if(section.code){html+=`<div class="doc-code-header"><span>${safe(section.language||'ath')} · ${lang==='pt'?'copiar exemplo':'example'}</span><button class="doc-copy" data-idx="${i}">${lang==='pt'?'Copiar':'Copy'} ⧉</button></div><pre><code>${window.Aletheia.highlight(section.code)}</code></pre>`}html+='</section>'});$('#docs-article').innerHTML=html;
$('#docs-article').querySelectorAll('.doc-copy').forEach(btn=>btn.addEventListener('click',()=>window.Aletheia.copyText(topic.parts[Number(btn.dataset.idx)].code)));
$('#docs-toc-links').innerHTML=topic.parts.map((sec,i)=>`<a href="#section-${i}" class="toc-link">${safe(sec[lang])}</a>`).join('');$('#doc-prevnext').innerHTML=(idx>0?`<a class="doc-pager" href="#${TOPICS[idx-1].id}"><small>← ${lang==='en'?'PREVIOUS':'ANTERIOR'}</small>${safe(TOPICS[idx-1][lang])}</a>`:'<span></span>')+(idx<TOPICS.length-1?`<a class="doc-pager" href="#${TOPICS[idx+1].id}"><small>${lang==='en'?'NEXT':'PRÓXIMO'} →</small>${safe(TOPICS[idx+1][lang])}</a>`:'<span></span>');}
function setTopic(id,update=true,scroll=true){if(id==='start')id='install';if(!TOPICS.some(x=>x.id===id))id='overview';active=id;nav();article();if(update)history.replaceState(null,'','#'+id);if(scroll)window.scrollTo({top:document.querySelector('.docs-shell').getBoundingClientRect().top+scrollY-85,behavior:'smooth'})}
function init(){const lang=currentLanguage();$('#docs-hero-title').textContent=lang==='en'?'The knowledge':'A base de';$('#docs-hero-accent').textContent=lang==='en'?'base.':'conhecimento.';$('#docs-hero-desc').textContent=lang==='en'?'A guided technical library for the language, compiler, runtime, proofs and empirical methods. Every claim is connected to the current research baseline.':'Uma biblioteca técnica navegável para linguagem, compilador, runtime, provas e métodos empíricos. Cada afirmação é vinculada à base de pesquisa atual.';$('#docs-search').placeholder=lang==='en'?'Search documentation...':'Pesquisar documentação...';$('#docs-search-hint').textContent=lang==='en'?'⌘ K / Ctrl K to search':'⌘ K / Ctrl K para pesquisar';$('#docs-sidebar-label').textContent=lang==='en'?'NAVIGATE THE LANGUAGE':'NAVEGUE PELA LINGUAGEM';$('#docs-toc-title').textContent=lang==='en'?'ON THIS PAGE':'NESTA PÁGINA';}
function setup(){init();$('#docs-search').addEventListener('input',e=>{query=e.target.value.trim().toLowerCase();nav()});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#docs-search').focus()}if(e.key==='Escape'&&document.activeElement===$('#docs-search')){$('#docs-search').blur()}});document.addEventListener('aletheia:locale',()=>{init();nav();article()});window.addEventListener('hashchange',()=>{const key=location.hash.slice(1);if(TOPICS.some(t=>t.id===key)||key==='start')setTopic(key,false)});setTopic(location.hash.slice(1)||'rc1',false,Boolean(location.hash))}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',setup);else setup();
})();
